(async () => {
    await esbuild.build({
        supported: {
            "dynamic-import": true
        },
        // application entry point
        entryPoints: ['src/index.js'],
        format: 'esm',
        bundle: true,
        minify: true,
        treeShaking: true,
        target: ['chrome60','firefox60','safari12'],
        // bundled application
